111	async fn build_auth_step_2(
112	    device: &Arc<MiWearDevice>,
113	    p_random: &[u8],
114	    device_verify: &pb::protocol::auth::DeviceVerify,
115	) -> Result<pb::protocol::WearPacket> {
116	    let mut state = device.state.write().await;
117	
118	    let w_random = device_verify.__OPENSOURCE_DELETED__.clone();
119	    let w_sign = device_verify.__OPENSOURCE_DELETED__.clone();
120	
121	    if w_random.len() != 16 || w_sign.len() != 32 {
122	        return Err(anyhow!("nonce/hmac length mismatch"));
123	    }
124	
125	    let block = kdf_miwear(
126	        &string_to_u8_16(&state.authkey).unwrap(),
127	        p_random.try_into().unwrap(),
128	        &w_random.clone().try_into().unwrap(),
129	    );
130	    let dec_key = &block[0..16];
131	    let enc_key = &block[16..32];
132	    let dec_nonce = &block[32..36];
133	    let enc_nonce = &block[36..40];
134	
135	    // 校验 HMAC ---
136	    let mut mac = hmac::Hmac::<Sha256>::new_from_slice(dec_key).unwrap();
137	    mac.update(&w_random);
138	    mac.update(p_random);
139	    let expect = mac.finalize().into_bytes();
140	    if w_sign != expect.as_slice() {
141	        return Err(anyhow!("Auth HMAC mismatch - wrong auth key?"));
142	    }
143	
144	    // encryptedSigns (HMAC) ---
145	    let mut mac2 = hmac::Hmac::<Sha256>::new_from_slice(enc_key).unwrap();
146	    mac2.update(p_random);
147	    mac2.update(&w_random);
148	    let encrypted_signs = mac2.finalize().into_bytes().to_vec(); // 32 B
149	
150	    let proto_companion_device = pb::protocol::CompanionDevice {
151	        __OPENSOURCE_DELETED__: pb::protocol::companion_device::DeviceType::Android as i32, // 写死安卓以解锁全部功能
152	        __OPENSOURCE_DELETED__: None,
153	        __OPENSOURCE_DELETED__: "AstroBox".to_string(),
154	        __OPENSOURCE_DELETED__: Some(0xffffffff), // 解锁全部capability 0xffffffff
155	        __OPENSOURCE_DELETED__: None,
156	        __OPENSOURCE_DELETED__: None,
157	    };
158	
159	    let companion_device = proto_companion_device.encode_to_vec();
160	    let pkt_nonce = {
161	        let mut n = Vec::with_capacity(12);
162	        n.extend_from_slice(enc_nonce); // 4B
163	        n.extend_from_slice(&0u32.to_le_bytes()); // counterHi
164	        n.extend_from_slice(&0u32.to_le_bytes()); // counterLo (i=0)
165	        n
166	    };
167	    let encrypted_device_info = aes128_ccm_encrypt(
168	        enc_key.try_into().unwrap(),
169	        &pkt_nonce.try_into().unwrap(),
170	        &[],
171	        &companion_device,
172	    );
173	
174	    let account_payload = pb::protocol::auth::AppConfirm {
175	        __OPENSOURCE_DELETED__: encrypted_signs,
176	        __OPENSOURCE_DELETED__: encrypted_device_info,
177	    };
178	
179	    let pkt_payload = pb::protocol::Account {
180	        __OPENSOURCE_DELETED__: Some(pb::protocol::account::Payload::AuthAppConfirm(account_payload)),
181	    };
182	
183	    let pkt = pb::protocol::WearPacket {
184	        __OPENSOURCE_DELETED__: pb::protocol::wear_packet::Type::Account as i32,
185	        __OPENSOURCE_DELETED__: pb::protocol::account::AccountId::AuthConfirm as u32,
186	        __OPENSOURCE_DELETED__: Some(pb::protocol::wear_packet::Payload::Account(pkt_payload)),
187	    };
188	
189	    state.sec_keys = Some(super::SecurityKeys {
190	        enc_key: enc_key.to_vec(),
191	        dec_key: dec_key.to_vec(),
192	        enc_nonce: enc_nonce.to_vec(),
193	        dec_nonce: dec_nonce.to_vec(),
194	    });
195	
196	    Ok(pkt)
197	}
