199	fn string_to_u8_16(s: &String) -> Option<[u8; 16]> {
200	    if s.len() != 32 {
201	        return None;
202	    }
203	
204	    let mut result = [0u8; 16];
205	    for i in 0..16 {
206	        let byte_str = &s[i * 2..i * 2 + 2];
207	        match u8::from_str_radix(byte_str, 16) {
208	            Ok(val) => result[i] = val,
209	            Err(_) => return None,
210	        }
211	    }
212	    Some(result)
213	}
