215	fn kdf_miwear(secret_key: &[u8; 16], phone_nonce: &[u8; 16], watch_nonce: &[u8; 16]) -> [u8; 64] {
216	    type HmacSha256 = Hmac<Sha256>;
217	
218	    // 1) hmac_key = HMAC(init_key, secret_key)
219	    let mut init_key = [0u8; 32];
220	    init_key[..16].copy_from_slice(phone_nonce);
221	    init_key[16..].copy_from_slice(watch_nonce);
222	
223	    let mut mac = HmacSha256::new_from_slice(&init_key).expect("HMAC key length fixed");
224	    mac.update(secret_key);
225	    let hmac_key = mac.finalize().into_bytes(); // 32 B
226	
227	    // 2) expand to 64 B
228	    let mut okm = [0u8; 64];
229	    let tag = b"miwear-auth";
230	    let mut offset = 0;
231	    let mut prev: Vec<u8> = Vec::new();
232	    for counter in 1u8..=3 {
233	        // 3*32 >= 64
234	        let mut mac = HmacSha256::new_from_slice(&hmac_key).unwrap();
235	        mac.update(&prev);
236	        mac.update(tag);
237	        mac.update(&[counter]);
238	        prev = mac.finalize().into_bytes().to_vec();
239	        let end = (offset + 32).min(64);
240	        okm[offset..end].copy_from_slice(&prev[..end - offset]);
241	        offset = end;
242	    }
243	    okm
244	}
