99	impl MiWearPacket {
100	    /* -- 解析 ------------------------------------------------ */
101	    pub fn parse(buf: &[u8]) -> Result<Self, &'static str> {
102	        if buf.len() < 8 {
103	            return Err("Incomplete header");
104	        }
105	        if &buf[..2] != MAGIC {
106	            return Err("Magic mismatch");
107	        }
108	
109	        let pkt_type = PktType::from(buf[2]);
110	        let seq = buf[3];
111	        let len = u16::from_le_bytes(buf[4..6].try_into().unwrap()) as usize;
112	        let frame_sz = 8 + len;
113	        if buf.len() < frame_sz {
114	            return Err("Incomplete frame");
115	        }
116	
117	        let crc_given = u16::from_le_bytes(buf[6..8].try_into().unwrap());
118	        let crc_calc = crc16_arc(&buf[8..frame_sz]);
119	        if crc_given != crc_calc {
120	            return Err("CRC mismatch");
121	        }
122	
123	        Ok(Self {
124	            pkt_type,
125	            seq,
126	            body: buf[8..frame_sz].to_vec(), // ← 拷贝进 Vec
127	        })
128	    }
129	
130	    /* -- 批量解析 ------------------------------------------- */
131	    pub fn parse_all(buf: &[u8]) -> Result<Vec<Self>, &'static str> {
132	        let mut packets = Vec::new();
133	        let mut idx = 0;
134	
135	        while idx < buf.len() {
136	            if buf[idx..].starts_with(&MAGIC) {
137	                // ok
138	            } else if let Some(rel) = buf[idx + 1..].iter().position(|&b| b == MAGIC[0]) {
139	                idx += rel + 1;
140	                continue;
141	            } else {
142	                return Err("Magic not found");
143	            }
144	
145	            let pkt = Self::parse(&buf[idx..])?;
146	            let frame_sz = 8 + pkt.body.len();
147	            packets.push(pkt);
148	            idx += frame_sz;
149	        }
150	        Ok(packets)
151	    }
