175	
176	        let mut out = Vec::with_capacity(8 + self.body.len());
177	        out.extend_from_slice(&MAGIC);
178	        out.push(self.pkt_type.into());
179	        out.push(self.seq);
180	        out.extend_from_slice(&len.to_le_bytes());
181	        out.extend_from_slice(&crc.to_le_bytes());
182	        out.extend_from_slice(&self.body);
183	        out
