202	fn crc16_arc(data: &[u8]) -> u16 {
203	    let mut crc: u16 = 0x0000;
204	    for &byte in data {
205	        crc ^= byte as u16;
206	        for _ in 0..8 {
207	            crc = if (crc & 0x0001) != 0 {
208	                (crc >> 1) ^ 0xA001 // 0x8005 reflected
209	            } else {
210	                crc >> 1
211	            };
212	        }
213	    }
214	    crc
215	}
